+      color: #000000;
+      transform: translateY(-140%);
+      transition: transform 0.2s ease;
+    }
+
+    .skip-link:focus {
+      transform: translateY(0);
+      outline: 2px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    main {
+      width: min(100%, 460px);
+    }
+
+    .card {
+      padding: 32px;
+      border: 1px solid var(--panel-border);
+      border-radius: 20px;
+      background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01)), var(--panel);
+      box-shadow: var(--shadow);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(1.6rem, 3vw, 2rem);
+      line-height: 1.2;
+    }
+
+    p {
+      margin: 0;
+      color: var(--muted);
+      line-height: 1.5;
+    }
+
+    form {
+      margin-top: 24px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 18px;
+      border: 1px solid var(--panel-border);
+      border-radius: 16px;
+      background: rgba(255, 255, 255, 0.02);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 12px;
+    }
+
+    input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin-top: 0.15rem;
+      accent-color: var(--accent);
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.45;
+    }
+
+    .helper-text {
+      font-size: 0.95rem;
+      color: var(--muted);
+    }
+
+    button {
+      width: 100%;
+      margin-top: 18px;
+      padding: 14px 18px;
+      border: 1px solid transparent;
+      border-radius: 14px;
+      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
+      color: #0b1020;
+      font: inherit;
+      font-weight: 700;
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+    }
+
+    input:focus-visible,
+    button:focus-visible {
+      outline: 2px solid var(--accent-strong);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin-top: 14px;
+      color: var(--muted);
+    }
+
+    .status.success {
+      padding: 12px 14px;
+      border: 1px solid var(--success-border);
+      border-radius: 12px;
+      background: var(--success-bg);
+      color: var(--success-text);
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 24px;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field,
+      button {
+        border-color: ButtonText;
+      }
+
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+      }
+
+      .status.success {
+        border-color: ButtonText;
+        background: Canvas;
+        color: CanvasText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content">
+    <section class="card" aria-labelledby="form-title">
+      <h1 id="form-title">Terms of use</h1>
+      <p>Please confirm your agreement before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="terms-consent"
+              name="terms-consent"
+              type="checkbox"
+              required
+              aria-describedby="terms-help"
+            >
+            <label for="terms-consent">I agree to the terms of use.</label>
+          </div>
+          <p id="terms-help" class="helper-text">Required to submit this form.</p>
+        </div>
+
+        <button type="submit">Submit</button>
+        <div id="form-status" class="status" aria-live="polite"></div>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById("consent-form");
+    const checkbox = document.getElementById("terms-consent");
+    const status = document.getElementById("form-status");
+
+    form.addEventListener("submit", function (event) {
+      if (!checkbox.checked) {
+        event.preventDefault();
+        checkbox.setCustomValidity("Please agree to the terms of use before submitting.");
+        checkbox.reportValidity();
+        checkbox.focus();
+        status.textContent = "";
+        status.className = "status";
+        return;
+      }
+
+      event.preventDefault();
+      checkbox.setCustomValidity("");
+      status.textContent = "Consent recorded. You can proceed.";
+      status.className = "status success";
+    });
+
+    checkbox.addEventListener("change", function () {
+      checkbox.setCustomValidity("");
+      if (checkbox.checked) {
+        status.textContent = "";
+        status.className = "status";
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
